toolScript:
// --- CORE VARIABLES ---
        let port;
        let reader;
        let inputField = document.getElementById('cmd-input');
        let logContainer = document.getElementById('terminal-log');
        let isConnected = false;
        let autoScroll = true;
        // --- STATS VARIABLES ---
        let txBytes = 0;
        let rxBytes = 0;
        let ledTimeoutRX;
        let ledTimeoutTX;
        // --- VISUALIZER VARIABLES ---
        const canvas = document.getElementById('signal-scope');
        const ctx = canvas.getContext('2d');
        let scopeData = new Array(100).fill(0); // Holds signal "noise" level
        // --- TOUR DATA ---
        const tourSteps = [
            { id: "tour-step-1", title: "Config & Connect", text: "Select your Baud Rate here. Most ESP32s use 115200. Click 'Initialize' to start the browser security handshake." },
            { id: "signal-scope", title: "Live Signal Scope", text: "Visualizes the incoming data stream noise. A flat line means silence; a jagged line means active communication." },
            { id: "terminal-log", title: "Console Output", text: "Your device logs appear here. Use color codes in your Arduino code for pretty printing!" },
            { id: "tour-step-3", title: "Command Uplink", text: "Type commands here. We automatically append \\r\\n (Carriage Return + New Line) for you." },
            { id: "stats-area", title: "Session Stats", text: "Track your data usage in real-time. Watch the TX/RX LEDs blink for immediate feedback." }
        ];
        let currentTourIndex = 0;
        // --- CORE SERIAL FUNCTIONS ---
        async function toggleConnect() {
            if (isConnected) {
                await disconnect();
            } else {
                await connect();
            }
        }
        async function connect() {
            if (!("serial" in navigator)) {
                showToast("Web Serial API not supported. Use Chrome/Edge.", "error");
                return;
            }
            try {
                port = await navigator.serial.requestPort();
                const baudRate = parseInt(document.getElementById('baudrate').value);
                await port.open({ baudRate });
                isConnected = true;
                updateStatus(true);
                logInfo(`Uplink established at ${baudRate} baud.`);
                // Show hint after 3 seconds
                setTimeout(() => {
                    const hintBox = document.getElementById('hint-box');
                    hintBox.style.display = 'block';
                    hintBox.classList.remove('hidden');
                }, 3000);
                readLoop();
                animateScope(); // Start visualizer
            } catch (err) {
                logInfo(`Connection Aborted: ${err.message}`, 'term-error');
            }
        }
        async function disconnect() {
            if (reader) {
                await reader.cancel();
            }
            if (port) {
                await port.close();
            }
            isConnected = false;
            updateStatus(false);
            logInfo("Uplink Terminated.");
        }
        async function readLoop() {
            while (port.readable && isConnected) {
                reader = port.readable.getReader();
                try {
                    while (true) {
                        const { value, done } = await reader.read();
                        if (done) break;
                        // Update Stats
                        rxBytes += value.length;
                        document.getElementById('stat-rx').innerText = rxBytes;
                        flashLed('rx');
                        // Update Visualizer Data (Simulated amplitude based on char codes)
                        if (value.length > 0) {
                            // Take average byte value as "amplitude" for visual effect
                            let avg = value.reduce((a, b) => a + b, 0) / value.length;
                            scopeData.push(avg);
                            scopeData.shift(); // Keep array size constant
                        }
                        const text = new TextDecoder().decode(value);
                        appendLog(text, 'term-in');
                    }
                } catch (err) {
                    console.error("Read loop error:", err);
                } finally {
                    reader.releaseLock();
                }
            }
        }
        async function sendCommand() {
            const cmd = inputField.value;
            if (!cmd && cmd !== "") return; // Allow empty string if user really wants
            if (!port || !port.writable) return;
            await writeToSerial(cmd + "\r\n");
            appendLog(`[TX] ${cmd}\n`, 'term-out');
            inputField.value = "";
        }
        async function sendQuickCmd(char) {
            if (!port || !port.writable) {
                showToast("Connect first!", "error");
                return;
            }
            await writeToSerial(char);
            appendLog(`[TX_KEY] ${char.charCodeAt(0)}\n`, 'term-out');
        }
        async function insertSample(text) {
            inputField.value = text;
            inputField.focus();
        }
        async function writeToSerial(dataStr) {
            const writer = port.writable.getWriter();
            const data = new TextEncoder().encode(dataStr);
            // Update Stats
            txBytes += data.length;
            document.getElementById('stat-tx').innerText = txBytes;
            flashLed('tx');
            await writer.write(data);
            writer.releaseLock();
        }
        function appendLog(text, className) {
            // Handle ANSI colors broadly (simple replacement)
            // Note: A full ANSI parser is complex, this is a basic "Red" support
            if (text.includes('\x1b[31m')) {
                className = 'term-error';
                text = text.replace(/\x1b\[31m/g, '').replace(/\x1b\[0m/g, '');
            }
            const span = document.createElement('span');
            span.className = className;
            span.innerText = text;
            logContainer.appendChild(span);
            if (autoScroll) {
                logContainer.scrollTop = logContainer.scrollHeight;
            }
        }
        function logInfo(msg, className = 'term-info') {
            const div = document.createElement('div');
            div.className = className;
            div.innerText = `[LOG] ${msg}`;
            logContainer.appendChild(div);
            logContainer.scrollTop = logContainer.scrollHeight;
        }
        // --- UI VISUALS & EFFECTS ---
        function flashLed(type) {
            const el = document.getElementById(`led-${type}`);
            const colorClass = type === 'rx' ? 'bg-emerald-400' : 'bg-amber-400';
            const baseClass = 'bg-slate-800';
            el.classList.remove(baseClass);
            el.classList.add(colorClass, 'shadow-[0_0_8px_rgba(255,255,255,0.8)]');
            const timeoutVar = type === 'rx' ? ledTimeoutRX : ledTimeoutTX;
            clearTimeout(timeoutVar);
            const newTimeout = setTimeout(() => {
                el.classList.remove(colorClass, 'shadow-[0_0_8px_rgba(255,255,255,0.8)]');
                el.classList.add(baseClass);
            }, 100); // 100ms flash
            if (type === 'rx') ledTimeoutRX = newTimeout;
            else ledTimeoutTX = newTimeout;
        }
        function updateStatus(connected) {
            const status = document.getElementById('connection-status');
            const sideStatus = document.getElementById('side-status');
            const btn = document.getElementById('connect-btn');
            if (connected) {
                status.innerHTML = '<span class="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]"></span> Link Active';
                sideStatus.innerHTML = '<div class="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div><span class="text-[9px] font-bold text-slate-900 uppercase">Online</span>';
                btn.innerText = "Terminate Link";
                btn.classList.replace('bg-amber-500', 'bg-red-600');
                btn.classList.replace('border-amber-800', 'border-red-900');
                inputField.disabled = false;
                inputField.placeholder = "Enter Command...";
            } else {
                status.innerHTML = '<span class="w-2.5 h-2.5 rounded-full bg-slate-300"></span> Link Offline';
                sideStatus.innerHTML = '<div class="w-2.5 h-2.5 bg-slate-300 rounded-full"></div><span class="text-[9px] font-bold text-slate-500 uppercase">Idle</span>';
                btn.innerText = "Initialize Connection";
                btn.classList.replace('bg-red-600', 'bg-amber-500');
                btn.classList.replace('border-red-900', 'border-amber-800');
                inputField.disabled = true;
                inputField.placeholder = "Awaiting uplink...";
            }
        }
        function clearLogs() {
            logContainer.innerHTML = "";
        }
        function toggleAutoScroll() {
            autoScroll = !autoScroll;
            const btn = document.getElementById('autoscroll-btn');
            if (autoScroll) {
                btn.innerText = "SCROLL: ON";
                btn.classList.replace('bg-slate-200', 'bg-amber-100');
                btn.classList.replace('text-slate-600', 'text-amber-800');
            } else {
                btn.innerText = "SCROLL: OFF";
                btn.classList.replace('bg-amber-100', 'bg-slate-200');
                btn.classList.replace('text-amber-800', 'text-slate-600');
            }
        }
        function showToast(msg, type = "info") {
            const toast = document.createElement('div');
            const bgClass = type === 'error' ? 'bg-red-600' : 'bg-slate-800';
            toast.className = `fixed top-24 left-1/2 -translate-x-1/2 ${bgClass} text-white px-8 py-3 rounded-full shadow-2xl z-[100] font-black text-xs uppercase tracking-widest animate-bounce`;
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 3000);
        }
        // --- VISUALIZER LOOP ---
        function animateScope() {
            if (!isConnected) {
                // Draw flat line when disconnected
                ctx.fillStyle = '#020617';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.beginPath();
                ctx.strokeStyle = '#1e293b';
                ctx.moveTo(0, canvas.height / 2);
                ctx.lineTo(canvas.width, canvas.height / 2);
                ctx.stroke();
                return;
            }
            // Clear
            ctx.fillStyle = '#020617';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            // Draw Grid
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 1;
            ctx.beginPath();
            for (let x = 0; x < canvas.width; x += 20) { ctx.moveTo(x, 0); ctx.lineTo(x, canvas.height); }
            ctx.stroke();
            // Draw Signal
            ctx.beginPath();
            ctx.strokeStyle = '#f59e0b'; // Amber
            ctx.lineWidth = 2;
            const step = canvas.width / scopeData.length;
            for (let i = 0; i < scopeData.length; i++) {
                // Map byte value (0-255) to height. 
                // We want mostly center, with spikes.
                // If data is 0, y is center.
                let val = scopeData[i];
                let y = (canvas.height / 2);
                if (val > 0) {
                    // create "jitter" effect based on value
                    let jitter = (Math.random() - 0.5) * (val / 5);
                    y += jitter;
                }
                if (i === 0) ctx.moveTo(i * step, y);
                else ctx.lineTo(i * step, y);
                // Decay value back to 0 slowly
                if (scopeData[i] > 0) scopeData[i] *= 0.9;
            }
            ctx.stroke();
            animateScope();
        }
        // --- TUTORIAL / TOUR LOGIC ---
        function startTour() {
            currentTourIndex = 0;
            document.getElementById('tour-overlay').style.display = 'block';
            window.scrollTo({ top: 100, behavior: 'smooth' }); // Scroll to top area
            renderTourStep();
        }
        function endTour() {
            const activeEl = document.getElementById(tourSteps[currentTourIndex].id);
            if (activeEl) activeEl.classList.remove('tour-spotlight', 'pulse-active');
            const tooltip = document.getElementById('active-tooltip');
            if (tooltip) tooltip.remove();
            document.getElementById('tour-overlay').style.display = 'none';
        }
        function renderTourStep() {
            // Remove previous highlights
            document.querySelectorAll('.tour-spotlight').forEach(el => el.classList.remove('tour-spotlight', 'pulse-active'));
            const oldTooltip = document.getElementById('active-tooltip');
            if (oldTooltip) oldTooltip.remove();
            if (currentTourIndex >= tourSteps.length) {
                endTour();
                return;
            }
            const step = tourSteps[currentTourIndex];
            const targetEl = document.getElementById(step.id);
            if (!targetEl) {
                // If element missing (e.g. mobile hidden), skip
                currentTourIndex++;
                renderTourStep();
                return;
            }
            // Add highlight
            targetEl.classList.add('tour-spotlight');
            if (currentTourIndex === 0) targetEl.classList.add('pulse-active'); // Pulse the first one
            // Calculate Position
            const rect = targetEl.getBoundingClientRect();
            const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
            // Create Tooltip
            const tooltip = document.createElement('div');
            tooltip.id = 'active-tooltip';
            tooltip.className = 'tour-tooltip';
            tooltip.innerHTML = `
                <h4 class="text-amber-600 font-bold uppercase text-xs tracking-widest mb-1">${step.title}</h4>
                <p class="text-slate-600 text-xs mb-3 leading-relaxed">${step.text}</p>
                <div class="flex justify-between items-center mt-2 border-t border-slate-100 pt-2">
                    <span class="text-[9px] text-slate-400 font-bold">${currentTourIndex + 1}/${tourSteps.length}</span>
                    <button onclick="nextTourStep()" class="bg-amber-500 text-white px-3 py-1 rounded text-[10px] font-bold uppercase hover:bg-amber-600 transition">Next</button>
                </div>
                <button onclick="endTour()" class="absolute top-1 right-2 text-slate-300 hover:text-red-400">&times;</button>
            `;
            // Position calculation (Top Center)
            document.body.appendChild(tooltip);
            // Need to append to body to calculate width correctly first
            const tooltipRect = tooltip.getBoundingClientRect();
            let topPos = rect.top + scrollTop - tooltipRect.height - 15;
            let leftPos = rect.left + (rect.width / 2) - (tooltipRect.width / 2);
            // Edge detection
            if (leftPos < 10) leftPos = 10;
            tooltip.style.top = topPos + 'px';
            tooltip.style.left = leftPos + 'px';
            // Smooth scroll to element if needed
            targetEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
        function nextTourStep() {
            currentTourIndex++;
            renderTourStep();
        }
        // --- EVENT LISTENERS ---
        inputField.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') sendCommand();
        });
        // Handle keyboard shortcuts
        document.addEventListener('keydown', (e) => {
            // CTRL+L to clear
            if (e.ctrlKey && e.key === 'l') {
                e.preventDefault();
                clearLogs();
            }
        });
        // Initialize Scroll to Top logic
        // Start visualizer empty loop
        requestAnimationFrame(animateScope);
